package findu.backend.notification.controller;import findu.backend.notification.dto.*;import findu.backend.notification.service.NotificationService;import lombok.RequiredArgsConstructor;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequiredArgsConstructor @RequestMapping("/api/notifications")public class NotificationController{final NotificationService s;@GetMapping public List<NotificationResponse> list(@AuthenticationPrincipal Long uid){return s.list(uid);}@PatchMapping("/read-all")public ResponseEntity<Void> readAll(@AuthenticationPrincipal Long uid){s.readAll(uid);return ResponseEntity.noContent().build();}@PatchMapping("/{id}/read")public ResponseEntity<Void> read(@AuthenticationPrincipal Long uid, @PathVariable Long id){s.read(uid,id);return ResponseEntity.noContent().build();}}
